32: /// TcpStream for outbound connections
33: #[pin_project]
34: pub struct TcpStream(#[pin] SysTcpStream);
35: 
36: impl TcpStream {
37:     /// Connects to address
38:     pub async fn connect_with_opts(addr: &SocketAddr, opts: &ConnectOpts) -> io::Result<Self> {
39:         // tcp_stream_connect(addr, opts).await.map(TcpStream)
40:         SysTcpStream::connect(*addr, opts).await.map(TcpStream)
41:     }
42: 
43:     /// Connects shadowsocks server
44:     pub async fn connect_server_with_opts(
45:         context: &Context,
46:         addr: &ServerAddr,
47:         opts: &ConnectOpts,
48:     ) -> io::Result<Self> {
49:         let stream = match *addr {
50:             ServerAddr::SocketAddr(ref addr) => SysTcpStream::connect(*addr, opts).await?,
51:             ServerAddr::DomainName(ref domain, port) => {
52:                 lookup_then_connect!(context, domain, port, |addr| {
53:                     SysTcpStream::connect(addr, opts).await
54:                 })?
55:                 .1
56:             }
57:         };
58: 
59:         Ok(Self(stream))
60:     }
61: 
62:     /// Connects proxy remote target
63:     pub async fn connect_remote_with_opts(context: &Context, addr: &Address, opts: &ConnectOpts) -> io::Result<Self> {
64:         let stream = match *addr {
65:             Address::SocketAddress(ref addr) => SysTcpStream::connect(*addr, opts).await?,
66:             Address::DomainNameAddress(ref domain, port) => {
67:                 lookup_then_connect!(context, domain, port, |addr| {
68:                     SysTcpStream::connect(addr, opts).await
69:                 })?
70:                 .1
71:             }
72:         };
73: 
74:         Ok(Self(stream))
75:     }
76: 
77:     /// Returns the local address that this stream is bound to.
78:     pub fn local_addr(&self) -> io::Result<SocketAddr> {
79:         self.0.local_addr()
80:     }
81: 
82:     /// Returns the remote address that this stream is connected to.
83:     pub fn peer_addr(&self) -> io::Result<SocketAddr> {
84:         self.0.peer_addr()
85:     }
86: 
87:     /// Gets the value of the `TCP_NODELAY` option on this socket.
88:     pub fn nodelay(&self) -> io::Result<bool> {
89:         self.0.nodelay()
90:     }
91: 
92:     /// Sets the value of the `TCP_NODELAY` option on this socket.
93:     pub fn set_nodelay(&self, nodelay: bool) -> io::Result<()> {
94:         self.0.set_nodelay(nodelay)
95:     }
96: }
