118: /// `TcpListener` for accepting inbound connections
119: #[derive(Debug)]
120: pub struct TcpListener {
121:     inner: TokioTcpListener,
122:     accept_opts: AcceptOpts,
123: }
124: 
125: impl TcpListener {
126:     /// Creates a new TcpListener, which will be bound to the specified address.
127:     pub async fn bind_with_opts(addr: &SocketAddr, accept_opts: AcceptOpts) -> io::Result<Self> {
128:         let socket = create_inbound_tcp_socket(addr, &accept_opts).await?;
129: 
130:         if let Some(size) = accept_opts.tcp.send_buffer_size {
131:             socket.set_send_buffer_size(size)?;
132:         }
133: 
134:         if let Some(size) = accept_opts.tcp.recv_buffer_size {
135:             socket.set_recv_buffer_size(size)?;
136:         }
137: 
138:         // On platforms with Berkeley-derived sockets, this allows to quickly
139:         // rebind a socket, without needing to wait for the OS to clean up the
140:         // previous one.
141:         //
142:         // On Windows, this allows rebinding sockets which are actively in use,
143:         // which allows “socket hijacking”, so we explicitly don't set it here.
144:         // https://docs.microsoft.com/en-us/windows/win32/winsock/using-so-reuseaddr-and-so-exclusiveaddruse
145:         #[cfg(not(windows))]
146:         socket.set_reuseaddr(true)?;
147: 
148:         let set_dual_stack = is_dual_stack_addr(addr);
149: 
150:         if set_dual_stack {
151:             socket_bind_dual_stack(&socket, addr, accept_opts.ipv6_only)?;
152:         } else {
153:             socket.bind(*addr)?;
154:         }
155: 
156:         // mio's default backlog is 1024
157:         let inner = socket.listen(1024)?;
158: 
159:         // Enable TFO if supported
160:         // macos requires TCP_FASTOPEN to be set after listen(), but other platform doesn't have this constraint
161:         if accept_opts.tcp.fastopen {
162:             set_tcp_fastopen(&inner)?;
163:         }
164: 
165:         Ok(Self { inner, accept_opts })
166:     }
167: 
168:     /// Create a `TcpListener` from tokio's `TcpListener`
169:     pub fn from_listener(listener: TokioTcpListener, accept_opts: AcceptOpts) -> io::Result<Self> {
170:         // Enable TFO if supported
171:         // macos requires TCP_FASTOPEN to be set after listen(), but other platform doesn't have this constraint
172:         if accept_opts.tcp.fastopen {
173:             set_tcp_fastopen(&listener)?;
174:         }
175: 
176:         Ok(Self {
177:             inner: listener,
178:             accept_opts,
179:         })
180:     }
181: 
182:     /// Polls to accept a new incoming connection to this listener.
183:     pub fn poll_accept(&self, cx: &mut task::Context<'_>) -> Poll<io::Result<(TokioTcpStream, SocketAddr)>> {
184:         let (stream, peer_addr) = ready!(self.inner.poll_accept(cx))?;
185:         set_common_sockopt_after_accept(&stream, &self.accept_opts)?;
186:         Poll::Ready(Ok((stream, peer_addr)))
187:     }
188: 
189:     /// Accept a new incoming connection to this listener
190:     pub async fn accept(&self) -> io::Result<(TokioTcpStream, SocketAddr)> {
191:         future::poll_fn(|cx| self.poll_accept(cx)).await
192:     }
193: 
194:     /// Unwraps and take the internal `TcpListener`
195:     pub fn into_inner(self) -> TokioTcpListener {
196:         self.inner
197:     }
198: }
199: 
200: impl Deref for TcpListener {
201:     type Target = TokioTcpListener;
202: 
203:     fn deref(&self) -> &Self::Target {
204:         &self.inner
205:     }
206: }
207: 
208: impl DerefMut for TcpListener {
209:     fn deref_mut(&mut self) -> &mut Self::Target {
210:         &mut self.inner
211:     }
212: }
213: 
214: impl From<TcpListener> for TokioTcpListener {
215:     fn from(listener: TcpListener) -> Self {
216:         listener.inner
217:     }
218: }
