}

#[inline(always)]
fn socket_call_warp<S, F>(stream: &S, f: F) -> io::Result<()>
where
    S: AsFd,
    F: FnOnce(&Socket) -> io::Result<()>,
{
    let socket = SockRef::from(stream);
