192: fn find_adapter_interface_index(addr: &SocketAddr, iface: &str) -> io::Result<Option<u32>> {
193:     // https://learn.microsoft.com/en-us/windows/win32/api/iphlpapi/nf-iphlpapi-getadaptersaddresses
194: 
195:     let ip = addr.ip();
196: 
197:     unsafe {
198:         let mut ip_adapter_addresses_buffer = BytesMut::with_capacity(15 * 1024);
199:         ip_adapter_addresses_buffer.set_len(15 * 1024);
200: 
201:         let mut ip_adapter_addresses_buffer_size: u32 = ip_adapter_addresses_buffer.len() as u32;
202:         loop {
203:             let ret = GetAdaptersAddresses(
204:                 AF_UNSPEC as u32,
205:                 GAA_FLAG_SKIP_UNICAST | GAA_FLAG_SKIP_ANYCAST | GAA_FLAG_SKIP_MULTICAST | GAA_FLAG_SKIP_DNS_SERVER,
206:                 ptr::null(),
207:                 ip_adapter_addresses_buffer.as_mut_ptr() as *mut _,
208:                 &mut ip_adapter_addresses_buffer_size as *mut _,
209:             );
210: 
211:             match ret {
212:                 ERROR_SUCCESS => break,
213:                 ERROR_BUFFER_OVERFLOW => {
214:                     // resize buffer to ip_adapter_addresses_buffer_size
215:                     ip_adapter_addresses_buffer.resize(ip_adapter_addresses_buffer_size as usize, 0);
216:                     continue;
217:                 }
218:                 ERROR_NO_DATA => return Ok(None),
219:                 _ => {
220:                     let err = io::Error::other(format!("GetAdaptersAddresses failed with error: {}", ret));
221:                     return Err(err);
222:                 }
223:             }
224:         }
225: 
226:         // IP_ADAPTER_ADDRESSES_LH is a linked-list
227:         let mut current_ip_adapter_address: *mut IP_ADAPTER_ADDRESSES_LH =
228:             ip_adapter_addresses_buffer.as_mut_ptr() as *mut _;
229:         while !current_ip_adapter_address.is_null() {
230:             let ip_adapter_address: &IP_ADAPTER_ADDRESSES_LH = &*current_ip_adapter_address;
231: 
232:             // Friendly Name
233:             let friendly_name_len: usize = libc::wcslen(ip_adapter_address.FriendlyName);
234:             let friendly_name_slice: &[u16] = slice::from_raw_parts(ip_adapter_address.FriendlyName, friendly_name_len);
235:             let friendly_name_os = OsString::from_wide(friendly_name_slice); // UTF-16 to UTF-8
236:             if let Some(friendly_name) = friendly_name_os.to_str()
237:                 && friendly_name == iface
238:             {
239:                 match ip {
240:                     IpAddr::V4(..) => return Ok(Some(ip_adapter_address.Anonymous1.Anonymous.IfIndex)),
241:                     IpAddr::V6(..) => return Ok(Some(ip_adapter_address.Ipv6IfIndex)),
242:                 }
243:             }
244: 
245:             // Adapter Name
246:             let adapter_name = CStr::from_ptr(ip_adapter_address.AdapterName as *mut _ as *const _);
247:             if adapter_name.to_bytes() == iface.as_bytes() {
248:                 match ip {
249:                     IpAddr::V4(..) => return Ok(Some(ip_adapter_address.Anonymous1.Anonymous.IfIndex)),
250:                     IpAddr::V6(..) => return Ok(Some(ip_adapter_address.Ipv6IfIndex)),
251:                 }
252:             }
253: 
254:             current_ip_adapter_address = ip_adapter_address.Next;
255:         }
256:     }
257: 
258:     Ok(None)
259: }
