261: fn find_interface_index_cached(addr: &SocketAddr, iface: &str) -> io::Result<u32> {
262:     const INDEX_EXPIRE_DURATION: Duration = Duration::from_secs(5);
263: 
264:     thread_local! {
265:         static INTERFACE_INDEX_CACHE: RefCell<HashMap<String, (u32, Instant)>> =
266:             RefCell::new(HashMap::new());
267:     }
268: 
269:     let cache_index = INTERFACE_INDEX_CACHE.with(|cache| cache.borrow().get(iface).cloned());
270:     if let Some((idx, insert_time)) = cache_index {
271:         // short-path, cache hit for most cases
272:         let now = Instant::now();
273:         if now - insert_time < INDEX_EXPIRE_DURATION {
274:             return Ok(idx);
275:         }
276:     }
277: 
278:     // Get from API GetAdaptersAddresses
279:     let idx = match find_adapter_interface_index(addr, iface)? {
280:         Some(idx) => idx,
281:         None => unsafe {
282:             // Windows if_nametoindex requires a C-string for interface name
283:             let ifname = CString::new(iface).expect("iface");
284: 
285:             // https://docs.microsoft.com/en-us/previous-versions/windows/hardware/drivers/ff553788(v=vs.85)
286:             let if_index = if_nametoindex(ifname.as_ptr() as PCSTR);
287:             if if_index == 0 {
288:                 // If the if_nametoindex function fails and returns zero, it is not possible to determine an error code.
289:                 error!("if_nametoindex {} fails", iface);
290:                 return Err(io::Error::new(ErrorKind::InvalidInput, "invalid interface name"));
291:             }
292: 
293:             if_index
294:         },
295:     };
296: 
297:     INTERFACE_INDEX_CACHE.with(|cache| {
298:         cache.borrow_mut().insert(iface.to_owned(), (idx, Instant::now()));
299:     });
300: 
301:     Ok(idx)
302: }
