304: fn set_ip_unicast_if<S: AsRawSocket>(socket: &S, addr: &SocketAddr, iface: &str) -> io::Result<()> {
305:     let handle = socket.as_raw_socket() as SOCKET;
306: 
307:     let if_index = find_interface_index_cached(addr, iface)?;
308: 
309:     unsafe {
310:         // https://docs.microsoft.com/en-us/windows/win32/winsock/ipproto-ip-socket-options
311:         let ret = match addr {
312:             SocketAddr::V4(..) => {
313:                 // Interface index is in network byte order for IPPROTO_IP.
314:                 let if_index = htonl(if_index);
315:                 setsockopt(
316:                     handle,
317:                     IPPROTO_IP,
318:                     IP_UNICAST_IF,
319:                     &if_index as *const _ as PCSTR,
320:                     mem::size_of_val(&if_index) as i32,
321:                 )
322:             }
323:             SocketAddr::V6(..) => {
324:                 // Interface index is in host byte order for IPPROTO_IPV6.
325:                 setsockopt(
326:                     handle,
327:                     IPPROTO_IPV6,
328:                     IPV6_UNICAST_IF,
329:                     &if_index as *const _ as PCSTR,
330:                     mem::size_of_val(&if_index) as i32,
331:                 )
332:             }
333:         };
334: 
335:         if ret == SOCKET_ERROR {
336:             let err = io::Error::from_raw_os_error(WSAGetLastError());
337:             error!(
338:                 "set IP_UNICAST_IF / IPV6_UNICAST_IF interface: {}, index: {}, error: {}",
339:                 iface, if_index, err
340:             );
341:             return Err(err);
342:         }
343:     }
344: 
345:     Ok(())
346: }
