348: fn disable_connection_reset(socket: &UdpSocket) -> io::Result<()> {
349:     let handle = socket.as_raw_socket() as SOCKET;
350: 
351:     unsafe {
352:         // Ignoring UdpSocket's WSAECONNRESET error
353:         // https://github.com/shadowsocks/shadowsocks-rust/issues/179
354:         // https://stackoverflow.com/questions/30749423/is-winsock-error-10054-wsaeconnreset-normal-with-udp-to-from-localhost
355:         //
356:         // This is because `UdpSocket::recv_from` may return WSAECONNRESET
357:         // if you called `UdpSocket::send_to` a destination that is not existed (may be closed).
358:         //
359:         // It is not an error. Could be ignored completely.
360:         // We have to ignore it here because it will crash the server.
361: 
362:         let mut bytes_returned: u32 = 0;
363:         let enable: BOOL = FALSE;
364: 
365:         let ret = WSAIoctl(
366:             handle,
367:             SIO_UDP_CONNRESET,
368:             &enable as *const _ as *const c_void,
369:             mem::size_of_val(&enable) as u32,
370:             ptr::null_mut(),
371:             0,
372:             &mut bytes_returned as *mut _,
373:             ptr::null_mut(),
374:             None,
375:         );
376: 
377:         if ret == SOCKET_ERROR {
378:             use std::io::Error;
379: 
380:             // Error occurs
381:             let err_code = WSAGetLastError();
382:             return Err(Error::from_raw_os_error(err_code));
383:         }
384:     }
385: 
386:     Ok(())
387: }
