389: /// Disable IP fragmentation
390: #[inline]
391: pub fn set_disable_ip_fragmentation<S: AsRawSocket>(af: AddrFamily, socket: &S) -> io::Result<()> {
392:     let handle = socket.as_raw_socket() as SOCKET;
393: 
394:     unsafe {
395:         // For Windows, IP_MTU_DISCOVER should be enabled for both IPv4 and IPv6 sockets
396:         // https://docs.microsoft.com/en-us/windows/win32/winsock/ipproto-ip-socket-options
397:         let value = IP_PMTUDISC_DO;
398:         let ret = setsockopt(
399:             handle,
400:             IPPROTO_IP,
401:             IP_MTU_DISCOVER,
402:             &value as *const _ as PCSTR,
403:             mem::size_of_val(&value) as i32,
404:         );
405: 
406:         if ret == SOCKET_ERROR {
407:             let err = io::Error::from_raw_os_error(WSAGetLastError());
408:             return Err(err);
409:         }
410: 
411:         if af == AddrFamily::Ipv6 {
412:             let value = IP_PMTUDISC_DO;
413:             let ret = setsockopt(
414:                 handle,
415:                 IPPROTO_IPV6,
416:                 IPV6_MTU_DISCOVER,
417:                 &value as *const _ as PCSTR,
418:                 mem::size_of_val(&value) as i32,
419:             );
420: 
421:             if ret == SOCKET_ERROR {
422:                 let err = io::Error::from_raw_os_error(WSAGetLastError());
423:                 return Err(err);
424:             }
425:         }
426:     }
427: 
428:     Ok(())
429: }
