433: /// It also disables `WSAECONNRESET` for UDP socket
434: pub async fn create_inbound_udp_socket(addr: &SocketAddr, ipv6_only: bool) -> io::Result<UdpSocket> {
435:     let set_dual_stack = is_dual_stack_addr(addr);
436: 
437:     let socket = if !set_dual_stack {
438:         UdpSocket::bind(addr).await?
